goog.locale.timezonelist.getTimeZoneAllLongNames = function() {
  'use strict';
  var locale = goog.locale.getLocale();
  return /** @type {Array<Object>} */ (
      goog.locale.getResource('TimeZoneAllLongNames', locale));
