  var getPrototypeOf = Object.getPrototypeOf;
  var getOwnPropertyDescriptor = Object.getOwnPropertyDescriptor;
  var cls = getPrototypeOf(target);
  while (cls != null) {
    cls = getPrototypeOf(cls);
    if (cls != null) {
